def tidy(v):
 if isinstance(v,str):
  for a,b in FIX.items():v=v.replace(a,b)
  v=re.sub(r'\b(Let|Take|Use|Fix|Choose|Set|Expand|Because|If|For|At|On)(?=[A-Zqxyz])',r'\1 ',v)
  v=re.sub(r'([,;])(?=[A-Za-z])',r'\1 ',v)
  v=re.sub(r'\b(and|or|the|with|for|when)(?=[A-Z](?:[₀₁₂₃]|[=∈⊆(]))',r'\1 ',v)
  return v
 if isinstance(v,list):return [tidy(x) for x in v]
 if isinstance(v,dict):return {k:tidy(x) for k,x in v.items()}
 return v
